import React, { useEffect, useMemo, useState } from 'react';
import api from '@/lib/api';

const SEMAFOROS = ['', 'VERDE', 'AMARILLO', 'ROJO'];
const PRIORIDADES = ['BAJA', 'MEDIA', 'ALTA', 'CRITICA'];

const pageStyle = { padding: 24, display: 'grid', gap: 16 };
const cardStyle = { border: '1px solid #e5e7eb', borderRadius: 12, padding: 16, background: '#fff' };
const inputStyle = { width: '100%', border: '1px solid #d1d5db', borderRadius: 8, padding: '8px 10px', minHeight: 36 };
const primaryButton = { border: '1px solid #111827', borderRadius: 8, padding: '8px 12px', background: '#111827', color: '#fff', fontWeight: 600, cursor: 'pointer' };
const secondaryButton = { ...primaryButton, background: '#fff', color: '#111827' };
const thStyle = { padding: 8, borderBottom: '1px solid #e5e7eb', textAlign: 'left', whiteSpace: 'nowrap' };
const tdStyle = { padding: 8, borderBottom: '1px solid #f3f4f6', verticalAlign: 'top' };

function formatMoney(value) {
  const parsed = Number(value || 0);
  return parsed.toLocaleString('es-MX', { style: 'currency', currency: 'MXN' });
}

function formatNumber(value, decimals = 2) {
  if (value === null || value === undefined || value === '') return '-';
  const parsed = Number(value);
  if (Number.isNaN(parsed)) return '-';
  return parsed.toLocaleString('es-MX', { minimumFractionDigits: decimals, maximumFractionDigits: decimals });
}

function formatDate(value) {
  if (!value) return '-';
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) return String(value);
  return parsed.toLocaleDateString('es-MX');
}

function badgeColors(value) {
  const normalized = String(value || '').toUpperCase();
  if (normalized === 'ROJO') return { background: '#fee2e2', color: '#991b1b' };
  if (normalized === 'AMARILLO') return { background: '#fef3c7', color: '#92400e' };
  if (normalized === 'VERDE') return { background: '#dcfce7', color: '#166534' };
  return { background: '#f3f4f6', color: '#374151' };
}

function SemaforoBadge({ value }) {
  return (
    <span style={{ ...badgeColors(value), borderRadius: 999, padding: '3px 8px', fontSize: 12, fontWeight: 700 }}>
      {value || 'SIN_DATOS'}
    </span>
  );
}

function KpiCard({ label, value, helper }) {
  return (
    <div style={cardStyle}>
      <div style={{ color: '#6b7280', fontSize: 12 }}>{label}</div>
      <strong style={{ display: 'block', fontSize: 24, marginTop: 4 }}>{value}</strong>
      {helper ? <div style={{ color: '#6b7280', fontSize: 12, marginTop: 4 }}>{helper}</div> : null}
    </div>
  );
}

export default function LotesProveedorPage() {
  const [rows, setRows] = useState([]);
  const [claims, setClaims] = useState([]);
  const [totalRows, setTotalRows] = useState(0);
  const [filters, setFilters] = useState({ lote: '', proveedor_id: '', semaforo: '' });
  const [selectedRow, setSelectedRow] = useState(null);
  const [drilldown, setDrilldown] = useState(null);
  const [claimForm, setClaimForm] = useState({ motivo: '', descripcion: '', prioridad: 'MEDIA' });
  const [loading, setLoading] = useState(false);
  const [detailLoading, setDetailLoading] = useState(false);
  const [claimSubmitting, setClaimSubmitting] = useState(false);
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');

  const kpis = useMemo(function calculateKpis() {
    const impacto = rows.reduce(function sum(acc, row) {
      return acc + Number(row.ImpactoEconomico || 0);
    }, 0);
    const rojos = rows.filter(function isRed(row) {
      return String(row.Semaforo || '').toUpperCase() === 'ROJO';
    }).length;
    const amarillos = rows.filter(function isYellow(row) {
      return String(row.Semaforo || '').toUpperCase() === 'AMARILLO';
    }).length;
    const reclamosAbiertos = claims.filter(function isOpen(claim) {
      return String(claim.Estatus || '').toUpperCase() === 'ABIERTO';
    }).length;
    return { impacto, rojos, amarillos, reclamosAbiertos };
  }, [rows, claims]);

  function updateFilter(field, value) {
    setFilters(function next(current) {
      return { ...current, [field]: value };
    });
  }

  function updateClaim(field, value) {
    setClaimForm(function next(current) {
      return { ...current, [field]: value };
    });
  }

  function buildRendimientosUrl() {
    const query = new URLSearchParams();
    query.set('limit', '100');
    query.set('offset', '0');
    if (filters.lote.trim()) query.set('lote', filters.lote.trim());
    if (filters.proveedor_id.trim()) query.set('proveedor_id', filters.proveedor_id.trim());
    if (filters.semaforo) query.set('semaforo', filters.semaforo);
    return '/tablajeria/lotes-proveedor/rendimientos?' + query.toString();
  }

  async function loadData() {
    setLoading(true);
    setError('');
    setNotice('');

    try {
      const lotesRes = await api.get(buildRendimientosUrl());
      const reclamosRes = await api.get('/tablajeria/reclamos-proveedor?limit=100');
      const nextRows = lotesRes.data && lotesRes.data.rendimientos ? lotesRes.data.rendimientos : [];
      const nextClaims = reclamosRes.data && reclamosRes.data.reclamos ? reclamosRes.data.reclamos : [];
      setRows(nextRows);
      setClaims(nextClaims);
      setTotalRows(lotesRes.data && lotesRes.data.total ? lotesRes.data.total : nextRows.length);
    } catch (err) {
      setError('No fue posible cargar lotes proveedor. Valida conexión, permisos o disponibilidad del backend.');
    } finally {
      setLoading(false);
    }
  }

  async function loadDrilldown(row) {
    if (!row || !row.LoteRendimientoID) {
      setError('El lote seleccionado no tiene identificador.');
      return;
    }

    setSelectedRow(row);
    setDrilldown(null);
    setDetailLoading(true);
    setError('');
    setNotice('');

    try {
      const response = await api.get('/tablajeria/lotes-proveedor/' + encodeURIComponent(row.LoteRendimientoID) + '/drilldown');
      setDrilldown(response.data || null);
    } catch (err) {
      setError('No fue posible cargar el detalle del lote proveedor.');
    } finally {
      setDetailLoading(false);
    }
  }

  async function submitClaim(event) {
    event.preventDefault();

    if (!selectedRow || !selectedRow.LoteRendimientoID) {
      setError('Selecciona un lote proveedor antes de abrir reclamo.');
      return;
    }

    if (!claimForm.motivo.trim()) {
      setError('Captura el motivo del reclamo.');
      return;
    }

    setClaimSubmitting(true);
    setError('');
    setNotice('');

    try {
      const payload = {
        motivo: claimForm.motivo.trim(),
        descripcion: claimForm.descripcion.trim() || null,
        prioridad: claimForm.prioridad,
        evidencia: {
          origen: 'EDARSAHUB_TABLAJERIA_LOTES_PROVEEDOR',
          loteProveedor: selectedRow.LoteProveedor || null,
          loteInterno: selectedRow.LoteInterno || null,
          semaforo: selectedRow.Semaforo || null,
          impactoEconomico: selectedRow.ImpactoEconomico || null
        }
      };

      const response = await api.post('/tablajeria/lotes-proveedor/' + encodeURIComponent(selectedRow.LoteRendimientoID) + '/reclamos', payload);
      setNotice('Reclamo creado' + (response.data && response.data.folio_reclamo ? ': ' + response.data.folio_reclamo : '.'));
      setClaimForm({ motivo: '', descripcion: '', prioridad: 'MEDIA' });
      await loadData();
      await loadDrilldown(selectedRow);
    } catch (err) {
      setError('No fue posible crear el reclamo proveedor.');
    } finally {
      setClaimSubmitting(false);
    }
  }

  useEffect(function init() {
    loadData();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const detalleLote = drilldown && drilldown.lote ? drilldown.lote : selectedRow;
  const detalleReclamos = drilldown && drilldown.reclamos ? drilldown.reclamos : [];
  const detalleNotificaciones = drilldown && drilldown.notificaciones ? drilldown.notificaciones : [];

  return (
    <div data-testid="tablajeria-lotes-proveedor" style={pageStyle}>
      <header style={{ display: 'flex', justifyContent: 'space-between', gap: 16, alignItems: 'flex-start' }}>
        <div>
          <h1 style={{ margin: 0 }}>Lotes proveedor</h1>
          <p style={{ margin: '6px 0 0', color: '#4b5563' }}>
            Rendimiento, desviaciones, impacto económico y reclamos por lote de compra.
          </p>
        </div>
        <button type="button" onClick={loadData} disabled={loading} style={primaryButton}>
          {loading ? 'Cargando...' : 'Actualizar'}
        </button>
      </header>

      {error ? <div role="alert" style={{ ...cardStyle, borderColor: '#fecaca', color: '#991b1b' }}>{error}</div> : null}
      {notice ? <div role="status" style={{ ...cardStyle, borderColor: '#bbf7d0', color: '#166534' }}>{notice}</div> : null}

      <section style={{ display: 'grid', gridTemplateColumns: 'repeat(4, minmax(0, 1fr))', gap: 12 }}>
        <KpiCard label="Lotes visibles" value={formatNumber(rows.length, 0)} helper={'Total: ' + formatNumber(totalRows, 0)} />
        <KpiCard label="Impacto económico" value={formatMoney(kpis.impacto)} />
        <KpiCard label="Alertas" value={formatNumber(kpis.rojos + kpis.amarillos, 0)} helper={'Rojas: ' + kpis.rojos + ' · Amarillas: ' + kpis.amarillos} />
        <KpiCard label="Reclamos abiertos" value={formatNumber(kpis.reclamosAbiertos, 0)} />
      </section>

      <section style={cardStyle}>
        <h2 style={{ marginTop: 0 }}>Filtros</h2>
        <div style={{ display: 'grid', gridTemplateColumns: '2fr 1.5fr 1fr auto', gap: 12, alignItems: 'end' }}>
          <label>
            <span>Lote proveedor / interno</span>
            <input value={filters.lote} onChange={function handle(event) { updateFilter('lote', event.target.value); }} placeholder="Buscar lote" style={inputStyle} />
          </label>
          <label>
            <span>Proveedor ID</span>
            <input value={filters.proveedor_id} onChange={function handle(event) { updateFilter('proveedor_id', event.target.value); }} placeholder="Opcional" style={inputStyle} />
          </label>
          <label>
            <span>Semáforo</span>
            <select value={filters.semaforo} onChange={function handle(event) { updateFilter('semaforo', event.target.value); }} style={inputStyle}>
              {SEMAFOROS.map(function option(value) {
                return <option key={value || 'TODOS'} value={value}>{value || 'TODOS'}</option>;
              })}
            </select>
          </label>
          <button type="button" onClick={loadData} disabled={loading} style={secondaryButton}>Aplicar</button>
        </div>
      </section>

      <section style={cardStyle}>
        <h2 style={{ marginTop: 0 }}>Rendimientos por lote</h2>
        <div style={{ overflowX: 'auto' }}>
          <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 13 }}>
            <thead>
              <tr>
                <th style={thStyle}>Lote</th>
                <th style={thStyle}>Proveedor</th>
                <th style={thStyle}>Orden</th>
                <th style={thStyle}>Kg base</th>
                <th style={thStyle}>Rend. esp.</th>
                <th style={thStyle}>Rend. real</th>
                <th style={thStyle}>Desv.</th>
                <th style={thStyle}>Merma kg</th>
                <th style={thStyle}>Impacto</th>
                <th style={thStyle}>Semáforo</th>
                <th style={thStyle}>Acción</th>
              </tr>
            </thead>
            <tbody>
              {rows.map(function renderRow(row, index) {
                const selected = selectedRow && selectedRow.LoteRendimientoID === row.LoteRendimientoID;
                return (
                  <tr key={row.LoteRendimientoID || row.LoteProveedor || index} style={{ background: selected ? '#f9fafb' : '#fff' }}>
                    <td style={tdStyle}>
                      <strong>{row.LoteProveedor || row.LoteInterno || 'Sin lote'}</strong>
                      <div style={{ color: '#6b7280', fontSize: 12 }}>{formatDate(row.FechaOperacionMexico)}</div>
                    </td>
                    <td style={tdStyle}>{row.ProveedorNombre || 'Sin proveedor'}</td>
                    <td style={tdStyle}>{row.FolioOrdenTablaje || '-'}</td>
                    <td style={tdStyle}>{formatNumber(row.CantidadBaseKg)}</td>
                    <td style={tdStyle}>{formatNumber(row.RendimientoEsperadoPorcentaje)}%</td>
                    <td style={tdStyle}>{formatNumber(row.RendimientoRealPorcentaje)}%</td>
                    <td style={tdStyle}>{formatNumber(row.DesviacionPorcentaje)}%</td>
                    <td style={tdStyle}>{formatNumber(row.MermaRealKg)}</td>
                    <td style={tdStyle}>{formatMoney(row.ImpactoEconomico)}</td>
                    <td style={tdStyle}><SemaforoBadge value={row.Semaforo} /></td>
                    <td style={tdStyle}>
                      <button type="button" onClick={function select() { loadDrilldown(row); }} style={secondaryButton}>Ver detalle</button>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
        {!rows.length && !loading ? <p>Sin registros.</p> : null}
      </section>

      <section style={{ display: 'grid', gridTemplateColumns: '2fr 1fr', gap: 16 }}>
        <div style={cardStyle}>
          <h2 style={{ marginTop: 0 }}>Drilldown del lote</h2>
          {!detalleLote ? <p>Selecciona un lote para ver trazabilidad proveedor → compra → recepción → tablajería → reclamos.</p> : null}
          {detailLoading ? <p>Cargando detalle...</p> : null}
          {detalleLote && !detailLoading ? (
            <div style={{ display: 'grid', gap: 10 }}>
              <div><strong>Lote proveedor:</strong> {detalleLote.LoteProveedor || '-'}</div>
              <div><strong>Lote interno:</strong> {detalleLote.LoteInterno || '-'}</div>
              <div><strong>Proveedor:</strong> {detalleLote.ProveedorNombre || '-'}</div>
              <div><strong>Orden compra:</strong> {detalleLote.OrdenCompraFolio || '-'}</div>
              <div><strong>Recepción:</strong> {detalleLote.RecepcionFolio || '-'}</div>
              <div><strong>Factura:</strong> {detalleLote.FacturaFolio || '-'}</div>
              <div><strong>Orden tablaje:</strong> {detalleLote.FolioOrdenTablaje || '-'}</div>
              <div><strong>Insumo base:</strong> {detalleLote.InsumoBaseCodigo || '-'} · {detalleLote.InsumoBaseNombre || '-'}</div>
              <div><strong>Impacto económico:</strong> {formatMoney(detalleLote.ImpactoEconomico)}</div>
              <div><strong>Semáforo:</strong> <SemaforoBadge value={detalleLote.Semaforo} /></div>
            </div>
          ) : null}

          {detalleReclamos.length ? (
            <div style={{ marginTop: 16 }}>
              <h3>Reclamos del lote</h3>
              <ul>
                {detalleReclamos.map(function renderClaim(claim, index) {
                  return <li key={claim.ReclamoProveedorID || claim.FolioReclamo || index}>{claim.FolioReclamo || 'Sin folio'} · {claim.Estatus || 'SIN_ESTATUS'} · {claim.Prioridad || 'SIN_PRIORIDAD'}</li>;
                })}
              </ul>
            </div>
          ) : null}

          {detalleNotificaciones.length ? (
            <div style={{ marginTop: 16 }}>
              <h3>Notificaciones</h3>
              <ul>
                {detalleNotificaciones.map(function renderNotification(item, index) {
                  return <li key={item.NotificacionLoteID || index}>{item.TipoNotificacion || 'Notificación'} · {item.Estatus || 'SIN_ESTATUS'}</li>;
                })}
              </ul>
            </div>
          ) : null}
        </div>

        <div style={cardStyle}>
          <h2 style={{ marginTop: 0 }}>Abrir reclamo</h2>
          {!selectedRow ? <p>Primero selecciona un lote.</p> : null}
          <form onSubmit={submitClaim} style={{ display: 'grid', gap: 10 }}>
            <label>
              <span>Motivo</span>
              <input value={claimForm.motivo} onChange={function handle(event) { updateClaim('motivo', event.target.value); }} placeholder="Ej. Bajo rendimiento" style={inputStyle} disabled={!selectedRow || claimSubmitting} />
            </label>
            <label>
              <span>Prioridad</span>
              <select value={claimForm.prioridad} onChange={function handle(event) { updateClaim('prioridad', event.target.value); }} style={inputStyle} disabled={!selectedRow || claimSubmitting}>
                {PRIORIDADES.map(function option(value) { return <option key={value} value={value}>{value}</option>; })}
              </select>
            </label>
            <label>
              <span>Descripción</span>
              <textarea value={claimForm.descripcion} onChange={function handle(event) { updateClaim('descripcion', event.target.value); }} placeholder="Detalle operativo del reclamo" style={{ ...inputStyle, minHeight: 90 }} disabled={!selectedRow || claimSubmitting} />
            </label>
            <button type="submit" style={primaryButton} disabled={!selectedRow || claimSubmitting}>
              {claimSubmitting ? 'Enviando...' : 'Crear reclamo'}
            </button>
          </form>
        </div>
      </section>

      <section style={cardStyle}>
        <h2 style={{ marginTop: 0 }}>Reclamos proveedor recientes</h2>
        <div style={{ overflowX: 'auto' }}>
          <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 13 }}>
            <thead>
              <tr>
                <th style={thStyle}>Folio</th>
                <th style={thStyle}>Proveedor</th>
                <th style={thStyle}>Motivo</th>
                <th style={thStyle}>Prioridad</th>
                <th style={thStyle}>Estatus</th>
                <th style={thStyle}>Impacto</th>
              </tr>
            </thead>
            <tbody>
              {claims.map(function renderClaim(claim, index) {
                return (
                  <tr key={claim.ReclamoProveedorID || claim.FolioReclamo || index}>
                    <td style={tdStyle}><strong>{claim.FolioReclamo || 'Sin folio'}</strong></td>
                    <td style={tdStyle}>{claim.ProveedorNombre || 'Sin proveedor'}</td>
                    <td style={tdStyle}>{claim.Motivo || '-'}</td>
                    <td style={tdStyle}>{claim.Prioridad || '-'}</td>
                    <td style={tdStyle}>{claim.Estatus || 'SIN_ESTATUS'}</td>
                    <td style={tdStyle}>{formatMoney(claim.ImpactoEconomico)}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
        {!claims.length && !loading ? <p>Sin reclamos.</p> : null}
      </section>
    </div>
  );
}
